sudo -n /usr/bin/python3 - <<'PY'
from pathlib import Path
import os,subprocess,json
src=Path('/root/iptvpn_bot')
base=Path('/srv/projects')
dst=base/'iptvpn-bot'
def call(args,sec=12):
 return subprocess.run(args,capture_output=True,text=True,timeout=sec)
def active(name):
 return call(['systemctl','is-active',name+'.service'],8).stdout.strip()
def bots():
 out=call(['pm2','jlist'],18)
 if out.returncode:raise RuntimeError('PM2 unavailable')
 return {a.get('name'):{'status':(a.get('pm2_env') or {}).get('status'),'pid':a.get('pid')} for a in json.loads(out.stdout) if a.get('name') in ('iptvpn_bot','telegram-robot-leads')}
units=['pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-root','nginx','postgresql@16-main','ssh']
old_units={u:active(u) for u in units}
if any(s!='active' for s in old_units.values()):raise RuntimeError('Systemd baseline not all active')
old_bots=bots()
if any(old_bots.get(x,{}).get('status')!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('PM2 baseline unhealthy')
if not src.is_dir() or src.is_symlink() or not (src/'.git').is_dir() or dst.exists() or dst.is_symlink():raise RuntimeError('Source or destination mismatch')
if base.exists() and (not base.is_dir() or base.is_symlink() or any(base.iterdir())):raise RuntimeError('Canonical parent not ready')
if src.stat().st_dev!=Path('/srv').stat().st_dev:raise RuntimeError('Cross filesystem')
remote=call(['git','-C',str(src),'remote','get-url','origin'])
if remote.returncode or 'martaxi-boss/iptvpn-bot' not in remote.stdout:raise RuntimeError('Wrong Git origin')
state=call(['git','-C',str(src),'status','--porcelain','--untracked-files=no'])
if state.returncode:raise RuntimeError('Git status failed')
sz=call(['du','-x','-s','-B1',str(src)],45)
if sz.returncode:raise RuntimeError('Source size unavailable')
bytes_before=int(sz.stdout.split()[0])
inode=src.stat().st_ino
if not (src/'start.sh').is_file() or not (src/'.venv/bin/python3').exists():raise RuntimeError('Bot entrypoint/venv absent')
if not base.exists():base.mkdir(mode=0o755)
moved=False
try:
 src.rename(dst)
 moved=True
 src.symlink_to(dst,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dst or dst.stat().st_ino!=inode:raise RuntimeError('Canonical move/symlink verification failed')
 if call(['/bin/bash','-n',str(dst/'start.sh')]).returncode:raise RuntimeError('Launcher syntax fails')
 py=call([str(dst/'.venv/bin/python3'),'-c','import sys; assert sys.version_info.major==3'],16)
 if py.returncode:raise RuntimeError('Python runtime not executable at canonical path')
 git=call(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'])
 if git.returncode or git.stdout!=state.stdout:raise RuntimeError('Git tracked state changed')
 measure=call(['du','-x','-s','-B1',str(dst)],45)
 if measure.returncode or int(measure.stdout.split()[0])!=bytes_before:raise RuntimeError('Directory bytes changed')
 for name,before in old_units.items():
  if active(name)!=before:raise RuntimeError('Systemd service state changed: '+name)
 now_bots=bots()
 for name,before in old_bots.items():
  if now_bots.get(name)!=before:raise RuntimeError('Bot status or PID changed: '+name)
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.exists() and not src.exists():dst.rename(src)
 if base.exists() and not any(base.iterdir()):base.rmdir()
 print('CANONICAL_MOVE_ROLLBACK=APPLIED')
 raise
print('CANONICAL_APP_PATH='+str(dst))
print('CANONICAL_ROOT_PHYSICAL=YES')
print('OLD_PATH_COMPAT_SYMLINK='+str(src))
print('CANONICAL_APP_BYTES='+str(bytes_before))
print('OLD_PYTHON_VALIDATION_CORRECTED=YES')
print('CANONICAL_PYTHON_TEST=PASS')
print('GIT_TRACKED_STATUS_UNCHANGED=YES')
print('PM2_BOTS_CONTINUOUSLY_ONLINE=YES')
print('PM2_PIDS_UNCHANGED=YES')
print('OTHER_SYSTEMD_SERVICES_UNCHANGED=YES')
print('PRIVATE_FILES_UNMODIFIED=YES')
print('DISK_SAVINGS_BYTES=0')
print('IPTVPN_CANONICAL_MOVE=PASS')
PY
